window.STAT_RESOURCES = {"meta": {"tb_total": 13, "lit_total": 100, "oa_total": 10, "generated": "2026-09-14"}, "textbooks": {"probability_and_statistics": [{"title": "MIT 1805 Lecture Notes Full", "file": "MIT_1805_Lecture_Notes_Full.pdf", "source": "开放授权教材/讲义", "size": "0.1MB"}, {"title": "NIST EDA ExploratoryDataAnalysis", "file": "NIST_EDA_ExploratoryDataAnalysis.pdf", "source": "开放授权教材/讲义", "size": "3.6MB"}, {"title": "Online Statistics Education DavidLane", "file": "Online_Statistics_Education_DavidLane.pdf", "source": "开放授权教材/讲义", "size": "34.1MB"}, {"title": "OpenIntro Statistics 4th", "file": "OpenIntro_Statistics_4th.pdf", "source": "开放授权教材/讲义", "size": "20.7MB"}, {"title": "NIST E-Handbook Statistical Methods full", "file": "NIST_E-Handbook_Statistical_Methods_full.pdf", "source": "开放授权教材", "size": "12.8MB", "root": true}, {"title": "NIST EDA exploratory data analysis", "file": "NIST_EDA_exploratory_data_analysis.pdf", "source": "开放授权教材", "size": "3.6MB", "root": true}, {"title": "OpenIntro Statistics 4th edition", "file": "OpenIntro_Statistics_4th_edition.pdf", "source": "开放授权教材", "size": "20.7MB", "root": true}], "regression_analysis": [{"title": "An Introduction to Statistical Learning ISLR", "file": "An_Introduction_to_Statistical_Learning_ISLR.pdf", "source": "开放授权教材/讲义", "size": "15.9MB"}, {"title": "NIST Process Characterization", "file": "NIST_Process_Characterization.pdf", "source": "开放授权教材/讲义", "size": "1.7MB"}], "design_of_experiments": [{"title": "NIST Design of Experiments", "file": "NIST_Design_of_Experiments.pdf", "source": "开放授权教材/讲义", "size": "2.8MB"}, {"title": "NIST Process Improvement", "file": "NIST_Process_Improvement.pdf", "source": "开放授权教材/讲义", "size": "0.9MB"}, {"title": "NIST Product Improvement", "file": "NIST_Product_Improvement.pdf", "source": "开放授权教材/讲义", "size": "0.4MB"}], "multivariate_statistics": [], "time_series": [{"title": "State Space Models Notes", "file": "State_Space_Models_Notes.pdf", "source": "开放授权教材/讲义", "size": "0.4MB"}], "survey_sampling": []}, "literature": {"probability_and_statistics": {"cn": "概率论与数理统计", "items": [{"title": "Fitting Linear Mixed-Effects Models Using lme4", "doi": "https://doi.org/10.18637/jss.v067.i01", "year": 2015, "authors": ["Douglas M. Bates", "Martin Mächler", "Benjamin M. Bolker", "Steve Walker"], "source": "Journal of Statistical Software", "cited": 88651, "abstract": "Maximum likelihood or restricted maximum likelihood (REML) estimates of the parameters in linear mixed-effects models can be determined using the lmer function in the lme4 package for R. As for most model-fitting functions in R, the model is described in an lmer call by a formula, in this case including both fixed- and random-effects terms. The formula and data together determine a numerical representation of the model from which the profiled deviance or the profiled REML criterion can be evaluated as a function of some of the model parameters. The appropriate criterion is optimized, using one of the constrained optimization functions in R, to provide the parameter estimates. We describe the structure of the model, the steps in evaluating the profiled deviance or REML criterion, and the st", "oa": true, "pdf_url": "https://www.jstatsoft.org/index.php/jss/article/view/v067i01/v67i01.pdf", "local_pdf": "000_Fitting Linear Mixed-Effects Models Usin.pdf", "api": ""}, {"title": "A new look at the statistical model identification", "doi": "https://doi.org/10.1109/tac.1974.1100705", "year": 1974, "authors": ["Hirotugu Akaike"], "source": "IEEE Transactions on Automatic Control", "cited": 51476, "abstract": "The history of the development of statistical hypothesis testing in time series analysis is reviewed briefly and it is pointed out that the hypothesis testing procedure is not adequately defined as the procedure for statistical model identification. The classical maximum likelihood estimation procedure is reviewed and a new estimate minimum information theoretical criterion (AIC) estimate (MAICE) which is designed for the purpose of statistical identification is introduced. When there are several competing models the MAICE is defined by the model and the maximum likelihood estimates of the parameters which give the minimum of AIC defined by AIC = (-2)log-(maximum likelihood) + 2(number of independently adjusted parameters within the model). MAICE provides a versatile procedure for statisti", "oa": true, "pdf_url": "https://doi.org/10.1109/tac.1974.1100705", "local_pdf": "", "api": ""}, {"title": "The central role of the propensity score in observational studies for causal effects", "doi": "https://doi.org/10.1093/biomet/70.1.41", "year": 1983, "authors": ["Paul R. Rosenbaum", "Donald B. Rubin"], "source": "Biometrika", "cited": 31472, "abstract": "The propensity score is the conditional probability of assignment to a particular treatment given a vector of observed covariates. Both large and small sample theory show that adjustment for the scalar propensity score is sufficient to remove bias due to all observed covariates. Applications include: (i) matched sampling on the univariate propensity score, which is a generalization of discriminant matching, (ii) multivariate adjustment by subclassification on the propensity score where the same subclasses are used to estimate treatment effects for all outcome variables and in all subpopulations, and (iii) visual representation of multivariate covariance adjustment by a two- dimensional plot.", "oa": true, "pdf_url": "https://academic.oup.com/biomet/article-pdf/70/1/41/662954/70-1-41.pdf", "local_pdf": "", "api": ""}, {"title": "Convex Optimization", "doi": "https://doi.org/10.1017/cbo9780511804441", "year": 2004, "authors": ["Stephen Boyd", "Lieven Vandenberghe"], "source": "Cambridge University Press eBooks", "cited": 31185, "abstract": "Convex optimization problems arise frequently in many different fields. This book provides a comprehensive introduction to the subject, and shows in detail how such problems can be solved numerically with great efficiency. The book begins with the basic elements of convex sets and functions, and then describes various classes of convex optimization problems. Duality and approximation techniques are then covered, as are statistical estimation techniques. Various geometrical problems are then presented, and there is detailed discussion of unconstrained and constrained minimization problems, and interior-point methods. The focus of the book is on recognizing convex optimization problems and then finding the most appropriate technique for solving them. It contains many worked examples and home", "oa": true, "pdf_url": "https://doi.org/10.1017/cbo9780511804441", "local_pdf": "", "api": ""}, {"title": "MrBayes 3.2: Efficient Bayesian Phylogenetic Inference and Model Choice Across a Large Model Space", "doi": "https://doi.org/10.1093/sysbio/sys029", "year": 2012, "authors": ["Fredrik Ronquist", "Maxim Teslenko", "Paul van der Mark", "Daniel L. Ayres", "Aaron E. Darling", "Sebastian Höhna"], "source": "Systematic Biology", "cited": 28551, "abstract": "Since its introduction in 2001, MrBayes has grown in popularity as a software package for Bayesian phylogenetic inference using Markov chain Monte Carlo (MCMC) methods. With this note, we announce the release of version 3.2, a major upgrade to the latest official release presented in 2003. The new version provides convergence diagnostics and allows multiple analyses to be run in parallel with convergence progress monitored on the fly. The introduction of new proposals and automatic optimization of tuning parameters has improved convergence for many problems. The new version also sports significantly faster likelihood calculations through streaming single-instruction-multiple-data extensions (SSE) and support of the BEAGLE library, allowing likelihood calculations to be delegated to graphic", "oa": true, "pdf_url": "https://academic.oup.com/sysbio/article-pdf/61/3/539/24563565/sys029.pdf", "local_pdf": "", "api": ""}, {"title": "MRBAYES: Bayesian inference of phylogenetic trees", "doi": "https://doi.org/10.1093/bioinformatics/17.8.754", "year": 2001, "authors": ["John P. Huelsenbeck", "Fredrik Ronquist"], "source": "Bioinformatics", "cited": 22301, "abstract": "SUMMARY: The program MRBAYES performs Bayesian inference of phylogeny using a variant of Markov chain Monte Carlo. AVAILABILITY: MRBAYES, including the source code, documentation, sample data files, and an executable, is available at http://brahms.biology.rochester.edu/software.html.", "oa": true, "pdf_url": "https://academic.oup.com/bioinformatics/article-pdf/17/8/754/48837190/bioinformatics_17_8_754.pdf", "local_pdf": "", "api": ""}, {"title": "Inference from Iterative Simulation Using Multiple Sequences", "doi": "https://doi.org/10.1214/ss/1177011136", "year": 1992, "authors": ["Andrew Gelman", "Donald B. Rubin"], "source": "Statistical Science", "cited": 17066, "abstract": "The Gibbs sampler, the algorithm of Metropolis and similar iterative simulation methods are potentially very helpful for summarizing multivariate distributions. Used naively, however, iterative simulation can give misleading answers. Our methods are simple and generally applicable to the output of any iterative simulation; they are designed for researchers primarily interested in the science underlying the data and models they are analyzing, rather than for researchers interested in the probability theory underlying the iterative simulations themselves. Our recommended strategy is to use several independent sequences, with starting points sampled from an overdispersed distribution. At each step of the iterative simulation, we obtain, for each univariate estimand of interest, a distribution", "oa": true, "pdf_url": "https://projecteuclid.org/journals/statistical-science/volume-7/issue-4/Inference-from-Iterative-Simulation-Using-Multiple-Sequences/10.1214/ss/1177011136.pdf", "local_pdf": "034_Bayesian inference for psychology. Part .pdf", "api": ""}, {"title": "Probability, Random Variables, and Stochastic Processes.", "doi": "https://doi.org/10.2307/2288754", "year": 1984, "authors": ["Julia Abrahams", "A. Papoulis"], "source": "Journal of the American Statistical Association", "cited": 16353, "abstract": "Part 1 Probability and Random Variables 1 The Meaning of Probability 2 The Axioms of Probability 3 Repeated Trials 4 The Concept of a Random Variable 5 Functions of One Random Variable 6 Two Random Variables 7 Sequences of Random Variables 8 Statistics Part 2 Stochastic Processes 9 General Concepts 10 Random Walk and Other Applications 11 Spectral Representation 12 Spectral Estimation 13 Mean Square Estimation 14 Entropy 15 Markov Chains 16 Markov Processes and Queueing Theory", "oa": true, "pdf_url": "https://doi.org/10.2307/2288754", "local_pdf": "", "api": ""}, {"title": "Maps of Dust Infrared Emission for Use in Estimation of Reddening and Cosmic Microwave Background Radiation Foregrounds", "doi": "https://doi.org/10.1086/305772", "year": 1998, "authors": ["David J. Schlegel", "Douglas P. Finkbeiner", "Marc Davis"], "source": "The Astrophysical Journal", "cited": 15395, "abstract": "We present a full-sky 100 μm map that is a reprocessed composite of the COBE /DIRBE and IRAS /ISSA maps, with the zodiacal foreground and confirmed point sources removed. Before using the ISSA maps, we remove the remaining artifacts from the IRAS scan pattern. Using the DIRBE 100 and 240 μm data, we have constructed a map of the dust temperature so that the 100 μm map may be converted to a map proportional to dust column density. The dust temperature varies from 17 to 21 K, which is modest but does modify the estimate of the dust column by a factor of 5. The result of these manipulations is a map with DIRBE quality calibration and IRAS resolution. A wealth of filamentary detail is apparent on many different scales at all Galactic latitudes. In high-latitude regions, the dust map correlates", "oa": true, "pdf_url": "https://iopscience.iop.org/article/10.1086/305772/pdf", "local_pdf": "", "api": ""}, {"title": "Statistical method for testing the neutral mutation hypothesis by DNA polymorphism.", "doi": "https://doi.org/10.1093/genetics/123.3.585", "year": 1989, "authors": ["Fumio Tajima"], "source": "Genetics", "cited": 14343, "abstract": "The relationship between the two estimates of genetic variation at the DNA level, namely the number of segregating sites and the average number of nucleotide differences estimated from pairwise comparison, is investigated. It is found that the correlation between these two estimates is large when the sample size is small, and decreases slowly as the sample size increases. Using the relationship obtained, a statistical method for testing the neutral mutation hypothesis is developed. This method needs only the data of DNA polymorphism, namely the genetic variation within population at the DNA level. A simple method of computer simulation, that was used in order to obtain the distribution of a new statistic developed, is also presented. Applying this statistical method to the five regions of ", "oa": true, "pdf_url": "https://academic.oup.com/genetics/article-pdf/123/3/585/34466400/genetics0585.pdf", "local_pdf": "", "api": ""}, {"title": "BEAST: Bayesian evolutionary analysis by sampling trees", "doi": "https://doi.org/10.1186/1471-2148-7-214", "year": 2007, "authors": ["Alexei J. Drummond", "Andrew Rambaut"], "source": "BMC Evolutionary Biology", "cited": 13193, "abstract": "BACKGROUND: The evolutionary analysis of molecular sequence variation is a statistical enterprise. This is reflected in the increased use of probabilistic models for phylogenetic inference, multiple sequence alignment, and molecular population genetics. Here we present BEAST: a fast, flexible software architecture for Bayesian analysis of molecular sequences related by an evolutionary tree. A large number of popular stochastic models of sequence evolution are provided and tree-based models suitable for both within- and between-species sequence data are implemented. RESULTS: BEAST version 1.4.6 consists of 81000 lines of Java source code, 779 classes and 81 packages. It provides models for DNA and protein sequence evolution, highly parametric coalescent analysis, relaxed clock phylogenetics", "oa": true, "pdf_url": "https://bmcecolevol.biomedcentral.com/counter/pdf/10.1186/1471-2148-7-214", "local_pdf": "", "api": ""}, {"title": "Theory of Superconductivity", "doi": "https://doi.org/10.1103/physrev.108.1175", "year": 1957, "authors": ["J. Bardeen", "Leon N. Cooper", "J. R. Schrieffer"], "source": "Physical Review", "cited": 13163, "abstract": "A theory of superconductivity is presented, based on the fact that the interaction between electrons resulting from virtual exchange of phonons is attractive when the energy difference between the electrons states involved is less than the phonon energy, $\\ensuremath{\\hbar}\\ensuremath{\\omega}$. It is favorable to form a superconducting phase when this attractive interaction dominates the repulsive screened Coulomb interaction. The normal phase is described by the Bloch individual-particle model. The ground state of a superconductor, formed from a linear combination of normal state configurations in which electrons are virtually excited in pairs of opposite spin and momentum, is lower in energy than the normal state by amount proportional to an average ${(\\ensuremath{\\hbar}\\ensuremath{\\omeg", "oa": true, "pdf_url": "http://link.aps.org/pdf/10.1103/PhysRev.108.1175", "local_pdf": "", "api": ""}, {"title": "Random effects structure for confirmatory hypothesis testing: Keep it maximal", "doi": "https://doi.org/10.1016/j.jml.2012.11.001", "year": 2013, "authors": ["Dale J. Barr", "Roger Lévy", "Christoph Scheepers", "Harry Tily"], "source": "Journal of Memory and Language", "cited": 10702, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1016/j.jml.2012.11.001", "local_pdf": "", "api": ""}, {"title": "Bayesian Analysis of Radiocarbon Dates", "doi": "https://doi.org/10.1017/s0033822200033865", "year": 2009, "authors": ["Christopher Bronk Ramsey"], "source": "Radiocarbon", "cited": 8790, "abstract": "If radiocarbon measurements are to be used at all for chronological purposes, we have to use statistical methods for calibration. The most widely used method of calibration can be seen as a simple application of Bayesian statistics, which uses both the information from the new measurement and information from the 14 C calibration curve. In most dating applications, however, we have larger numbers of 14 C measurements and we wish to relate those to events in the past. Bayesian statistics provides a coherent framework in which such analysis can be performed and is becoming a core element in many 14 C dating projects. This article gives an overview of the main model components used in chronological analysis, their mathematical formulation, and examples of how such analyses can be performed us", "oa": true, "pdf_url": "https://www.cambridge.org/core/services/aop-cambridge-core/content/view/F622173B70F9C1597F2738DEFC597114/S0033822200033865a.pdf/div-class-title-bayesian-analysis-of-radiocarbon-dates-div.pdf", "local_pdf": "013_Bayesian Analysis of Radiocarbon Dates.pdf", "api": ""}, {"title": "Inference of Population Structure Using Multilocus Genotype Data: Linked Loci and Correlated Allele Frequencies", "doi": "https://doi.org/10.1093/genetics/164.4.1567", "year": 2003, "authors": ["Daniel Falush", "Matthew Stephens", "Jonathan K. Pritchard"], "source": "Genetics", "cited": 8110, "abstract": "We describe extensions to the method of Pritchard et al. for inferring population structure from multilocus genotype data. Most importantly, we develop methods that allow for linkage between loci. The new model accounts for the correlations between linked loci that arise in admixed populations (\"admixture linkage disequilibium\"). This modification has several advantages, allowing (1) detection of admixture events farther back into the past, (2) inference of the population of origin of chromosomal regions, and (3) more accurate estimates of statistical uncertainty when linked loci are used. It is also of potential use for admixture mapping. In addition, we describe a new prior model for the allele frequencies within each population, which allows identification of subtle population subdivisi", "oa": true, "pdf_url": "https://academic.oup.com/genetics/article-pdf/164/4/1567/37401990/genetics1567.pdf", "local_pdf": "034_Bayesian inference for psychology. Part .pdf", "api": ""}, {"title": "The Theory of Probability", "doi": "https://doi.org/10.1038/109132a0", "year": 1922, "authors": ["Harold Jeffreys", "P. A. P. Moran", "C. Chatfield"], "source": "Nature", "cited": 6732, "abstract": "Abstract Jeffreys' Theory of Probability, first published in 1939, was the first attempt to develop a fundamental theory of scientific inference based on Bayesian statistics. His ideas were well ahead of their time and it is only in the past ten years that the subject of Bayes' factors has been significantly developed and extended. Recent work has made Bayesian statistics an essential subject for graduate students and researchers. This seminal book is their starting point.", "oa": true, "pdf_url": "https://www.nature.com/articles/109132a0.pdf", "local_pdf": "", "api": ""}, {"title": "Statistical Inference", "doi": "https://doi.org/10.1201/9781003456285", "year": 1993, "authors": ["George Casella", "Roger L. Berger"], "source": "Biometrics", "cited": 5366, "abstract": "This classic textbook builds theoretical statistics from the first principles of probability theory. Starting from the basics of probability, the authors develop the theory of statistical inference using techniques, definitions, and concepts that are statistical and natural extensions, and consequences, of previous concepts. It covers all topics from a standard inference course including: distributions, random variables, data reduction, point estimation, hypothesis testing, and interval estimation. Features The classic graduate-level textbook on statistical inference Develops elements of statistical theory from first principles of probability Written in a lucid style accessible to anyone with some background in calculus Covers all key topics of a standard course in inference Hundreds of ex", "oa": true, "pdf_url": "https://doi.org/10.2307/2532634", "local_pdf": "", "api": ""}, {"title": "Bayesian Test for Colocalisation between Pairs of Genetic Association Studies Using Summary Statistics", "doi": "https://doi.org/10.1371/journal.pgen.1004383", "year": 2014, "authors": ["Claudia Giambartolomei", "Damjan Vukcevic", "Eric E. Schadt", "Lude Franke", "Aroon D. Hingorani", "Chris Wallace"], "source": "PLoS Genetics", "cited": 4765, "abstract": "Genetic association studies, in particular the genome-wide association study (GWAS) design, have provided a wealth of novel insights into the aetiology of a wide range of human diseases and traits, in particular cardiovascular diseases and lipid biomarkers. The next challenge consists of understanding the molecular basis of these associations. The integration of multiple association datasets, including gene expression datasets, can contribute to this goal. We have developed a novel statistical methodology to assess whether two association signals are consistent with a shared causal variant. An application is the integration of disease scans with expression quantitative trait locus (eQTL) studies, but any pair of GWAS datasets can be integrated in this framework. We demonstrate the value of", "oa": true, "pdf_url": "https://journals.plos.org/plosgenetics/article/file?id=10.1371/journal.pgen.1004383&type=printable", "local_pdf": "017_Bayesian Test for Colocalisation between.pdf", "api": ""}, {"title": "Model Selection and Inference: A Practical Information-Theoretic Approach", "doi": "https://doi.org/10.2307/2669574", "year": 2000, "authors": ["Robert L. Strawderman", "Kenneth P. Burnham", "David R. Anderson"], "source": "Journal of the American Statistical Association", "cited": 4218, "abstract": "We wrote this book to introduce graduate students and research workers in various scientific disciplines to the use of information-theoretic approaches in the analysis of empirical data.In its fully developed form, the information-theoretic approach allows inference based on more than one model (including estimates of unconditional precision); in its initial form, it is useful in selecting a \"best\" model and ranking the remaining models.We believe that often the critical issue in data analysis is the selection of a good approximating model that best represents the inference supported by the data (an estimated \"best approximating model\").Information theory includes the well-known Kullback-Leibler \"distance\" between two models (actually, probability distributions), and this represents a fund", "oa": true, "pdf_url": "https://www.jstor.org/institutionSearch?redirectUri=%2fstable%2f2669574", "local_pdf": "", "api": ""}, {"title": "Bayesian t tests for accepting and rejecting the null hypothesis", "doi": "https://doi.org/10.3758/pbr.16.2.225", "year": 2009, "authors": ["Jeffrey N. Rouder", "Paul L. Speckman", "Dongchu Sun", "Richard D. Morey", "Geoffrey Iverson"], "source": "Psychonomic Bulletin & Review", "cited": 4006, "abstract": "", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.3758/PBR.16.2.225.pdf", "local_pdf": "017_Bayesian Test for Colocalisation between.pdf", "api": ""}, {"title": "Permutation inference for the general linear model", "doi": "https://doi.org/10.1016/j.neuroimage.2014.01.060", "year": 2014, "authors": ["Anderson M. Winkler", "Gerard R. Ridgway", "Matthew Webster", "Stephen M. Smith", "Thomas E. Nichols"], "source": "NeuroImage", "cited": 3878, "abstract": "Permutation methods can provide exact control of false positives and allow the use of non-standard statistics, making only weak assumptions about the data. With the availability of fast and inexpensive computing, their main limitation would be some lack of flexibility to work with arbitrary experimental designs. In this paper we report on results on approximate permutation methods that are more flexible with respect to the experimental design and nuisance variables, and conduct detailed simulations to identify the best method for settings that are typical for imaging research scenarios. We present a generic framework for permutation inference for complex general linear models (GLMS) when the errors are exchangeable and/or have a symmetric distribution, and show that, even in the presence o", "oa": true, "pdf_url": "https://www.sciencedirect.com/science/article/pii/S1053811914000913/pdf", "local_pdf": "", "api": ""}, {"title": "A Measure of Asymptotic Efficiency for Tests of a Hypothesis Based on the sum of Observations", "doi": "https://doi.org/10.1214/aoms/1177729330", "year": 1952, "authors": ["Herman Chernoff"], "source": "The Annals of Mathematical Statistics", "cited": 3642, "abstract": "In many cases an optimum or computationally convenient test of a simple hypothesis $H_0$ against a simple alternative $H_1$ may be given in the following form. Reject $H_0$ if $S_n = \\sum^n_{j=1} X_j \\leqq k,$ where $X_1, X_2, \\cdots, X_n$ are $n$ independent observations of a chance variable $X$ whose distribution depends on the true hypothesis and where $k$ is some appropriate number. In particular the likelihood ratio test for fixed sample size can be reduced to this form. It is shown that with each test of the above form there is associated an index $\\rho$. If $\\rho_1$ and $\\rho_2$ are the indices corresponding to two alternative tests $e = \\log \\rho_1/\\log \\rho_2$ measures the relative efficiency of these tests in the following sense. For large samples, a sample of size $n$ with the f", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-mathematical-statistics/volume-23/issue-4/A-Measure-of-Asymptotic-Efficiency-for-Tests-of-a-Hypothesis/10.1214/aoms/1177729330.pdf", "local_pdf": "", "api": ""}, {"title": "Causal Inference without Balance Checking: Coarsened Exact Matching", "doi": "https://doi.org/10.1093/pan/mpr013", "year": 2011, "authors": ["Stefano M. Iacus", "Gary King", "Giuseppe Porro"], "source": "Political Analysis", "cited": 3612, "abstract": "We discuss a method for improving causal inferences called “Coarsened Exact Matching” (CEM), and the new “Monotonic Imbalance Bounding” (MIB) class of matching methods from which CEM is derived. We summarize what is known about CEM and MIB, derive and illustrate several new desirable statistical properties of CEM, and then propose a variety of useful extensions. We show that CEM possesses a wide range of statistical properties not available in most other matching methods but is at the same time exceptionally easy to comprehend and use. We focus on the connection between theoretical properties and practical applications. We also make available easy-to-use open source software for R, Stata , and SPSS that implement all our suggestions.", "oa": true, "pdf_url": "https://www.cambridge.org/core/services/aop-cambridge-core/content/view/5ABCF5B3FC3089A87FD59CECBB3465C0/S1047198700012985a.pdf/div-class-title-causal-inference-without-balance-checking-coarsened-exact-matching-div.pdf", "local_pdf": "", "api": ""}, {"title": "Mathematical Statistics and Data Analysis", "doi": "https://doi.org/10.2307/3556160", "year": 1989, "authors": ["Larry Rabinowitz", "John A. Rice"], "source": "Technometrics", "cited": 3094, "abstract": "1. Probability. 2. Random Variables. 3. Joint Distributions. 4. Expected Values. 5. Limit Theorems. 6. Distributions Derived from the Normal Distribution. 7. Survey Sampling. 8. Estimation of Parameters and Fitting of Probability Distributions. 9. Testing Hypotheses and Assessing Goodness of Fit. 10. Summarizing Data. 11. Comparing Two Samples. 12. The Analysis of Variance. 13. The Analysis of Categorical Data. 14. Linear Least Squares. 15. Decision Theory and Bayesian Inference.", "oa": true, "pdf_url": "https://doi.org/10.2307/3556160", "local_pdf": "", "api": ""}, {"title": "Inference of Population Splits and Mixtures from Genome-Wide Allele Frequency Data", "doi": "https://doi.org/10.1371/journal.pgen.1002967", "year": 2012, "authors": ["Joseph K. Pickrell", "Jonathan K. Pritchard"], "source": "PLoS Genetics", "cited": 3066, "abstract": "Many aspects of the historical relationships between populations in a species are reflected in genetic data. Inferring these relationships from genetic data, however, remains a challenging task. In this paper, we present a statistical model for inferring the patterns of population splits and mixtures in multiple populations. In our model, the sampled populations in a species are related to their common ancestor through a graph of ancestral populations. Using genome-wide allele frequency data and a Gaussian approximation to genetic drift, we infer the structure of this graph. We applied this method to a set of 55 human populations and a set of 82 dog breeds and wild canids. In both species, we show that a simple bifurcating tree does not fully describe the data; in contrast, we infer many m", "oa": true, "pdf_url": "https://doi.org/10.1371/journal.pgen.1002967", "local_pdf": "034_Bayesian inference for psychology. Part .pdf", "api": ""}, {"title": "HyPhy: hypothesis testing using phylogenies", "doi": "https://doi.org/10.1093/bioinformatics/bti079", "year": 2004, "authors": ["Sergei L. Kosakovsky Pond", "Simon D. W. Frost", "Spencer V. Muse"], "source": "Bioinformatics", "cited": 3062, "abstract": "UNLABELLED: The HyPhypackage is designed to provide a flexible and unified platform for carrying out likelihood-based analyses on multiple alignments of molecular sequence data, with the emphasis on studies of rates and patterns of sequence evolution. AVAILABILITY: http://www.hyphy.org CONTACT: muse@stat.ncsu.edu SUPPLEMENTARY INFORMATION: HyPhydocumentation and tutorials are available at http://www.hyphy.org.", "oa": true, "pdf_url": "https://academic.oup.com/bioinformatics/article-pdf/21/5/676/48962517/bioinformatics_21_5_676.pdf", "local_pdf": "", "api": ""}, {"title": "Bayesian Inference of Species Trees from Multilocus Data", "doi": "https://doi.org/10.1093/molbev/msp274", "year": 2009, "authors": ["Joseph Heled", "Alexei J. Drummond"], "source": "Molecular Biology and Evolution", "cited": 2573, "abstract": "Until recently, it has been common practice for a phylogenetic analysis to use a single gene sequence from a single individual organism as a proxy for an entire species. With technological advances, it is now becoming more common to collect data sets containing multiple gene loci and multiple individuals per species. These data sets often reveal the need to directly model intraspecies polymorphism and incomplete lineage sorting in phylogenetic estimation procedures. For a single species, coalescent theory is widely used in contemporary population genetics to model intraspecific gene trees. Here, we present a Bayesian Markov chain Monte Carlo method for the multispecies coalescent. Our method coestimates multiple gene trees embedded in a shared species tree along with the effective populati", "oa": true, "pdf_url": "https://academic.oup.com/mbe/article-pdf/27/3/570/6314000/msp274.pdf", "local_pdf": "034_Bayesian inference for psychology. Part .pdf", "api": ""}, {"title": "Terrace Aware Data Structure for Phylogenomic Inference from Supermatrices", "doi": "https://doi.org/10.1093/sysbio/syw037", "year": 2016, "authors": ["Olga Chernomor", "Arndt von Haeseler", "Bùi Quang Minh"], "source": "Systematic Biology", "cited": 2415, "abstract": "In phylogenomics the analysis of concatenated gene alignments, the so-called supermatrix, is commonly accompanied by the assumption of partition models. Under such models each gene, or more generally partition, is allowed to evolve under its own evolutionary model. Although partition models provide a more comprehensive analysis of supermatrices, missing data may hamper the tree search algorithms due to the existence of phylogenetic (partial) terraces. Here, we introduce the phylogenetic terrace aware (PTA) data structure for the efficient analysis under partition models. In the presence of missing data PTA exploits (partial) terraces and induced partition trees to save computation time. We show that an implementation of PTA in IQ-TREE leads to a substantial speedup of up to 4.5 and 8 times", "oa": true, "pdf_url": "https://academic.oup.com/sysbio/article-pdf/65/6/997/19609034/syw037.pdf", "local_pdf": "", "api": ""}, {"title": "Causal inference in statistics: An overview", "doi": "https://doi.org/10.1214/09-ss057", "year": 2009, "authors": ["Judea Pearl"], "source": "Statistics Surveys", "cited": 2395, "abstract": "This review presents empirical researchers with recent advances in causal inference, and stresses the paradigmatic shifts that must be undertaken in moving from traditional statistical analysis to causal analysis of multivariate data. Special emphasis is placed on the assumptions that underly all causal inferences, the languages used in formulating those assumptions, the conditional nature of all causal and counterfactual claims, and the methods that have been developed for the assessment of such claims. These advances are illustrated using a general theory of causation based on the Structural Causal Model (SCM) described in Pearl (2000a), which subsumes and unifies other approaches to causation, and provides a coherent mathematical foundation for the analysis of causes and counterfactuals", "oa": true, "pdf_url": "https://projecteuclid.org/journals/statistics-surveys/volume-3/issue-none/Causal-inference-in-statistics-An-overview/10.1214/09-SS057.pdf", "local_pdf": "", "api": ""}, {"title": "Stochastic Volatility: Likelihood Inference and Comparison with ARCH Models", "doi": "https://doi.org/10.1111/1467-937x.00050", "year": 1998, "authors": ["Sang‐Joon Kim", "Neil Shepherd", "Siddhartha Chib"], "source": "The Review of Economic Studies", "cited": 2342, "abstract": "In this paper, Markov chain Monte Carlo sampling methods are exploited to provide a unified, practical likelihood-based framework for the analysis of stochastic volatility models. A highly effective method is developed that samples all the unobserved volatilities at once using an approximating offset mixture model, followed by an importance reweighting procedure. This approach is compared with several alternative methods using real data. The paper also develops simulation-based methods for filtering, likelihood evaluation and model failure diagnostics. The issue of model choice using non-nested likelihood ratios and Bayes factors is also investigated. These methods are used to compare the fit of stochastic volatility and GARCH models. All the procedures are illustrated in detail.", "oa": true, "pdf_url": "https://doi.org/10.1111/1467-937x.00050", "local_pdf": "", "api": ""}, {"title": "A brief introduction to mixed effects modelling and multi-model inference in ecology", "doi": "https://doi.org/10.7717/peerj.4794", "year": 2018, "authors": ["Xavier A. Harrison", "Lynda Donaldson", "Maria Correa-Cano", "Julian Evans", "David N. Fisher", "Cecily Goodwin"], "source": "PeerJ", "cited": 2133, "abstract": "The use of linear mixed effects models (LMMs) is increasingly common in the analysis of biological data. Whilst LMMs offer a flexible approach to modelling a broad range of data types, ecological data are often complex and require complex model structures, and the fitting and interpretation of such models is not always straightforward. The ability to achieve robust biological inference requires that practitioners know how and when to apply these tools. Here, we provide a general overview of current methods for the application of LMMs to biological data, and highlight the typical pitfalls that can be encountered in the statistical modelling process. We tackle several issues regarding methods of model selection, with particular reference to the use of information theory and multi-model infer", "oa": true, "pdf_url": "https://doi.org/10.7717/peerj.4794", "local_pdf": "", "api": ""}, {"title": "Confidence intervals rather than P values: estimation rather than hypothesis testing.", "doi": "https://doi.org/10.1136/bmj.292.6522.746", "year": 1986, "authors": ["Michael Gardner", "Douglas G. Altman"], "source": "BMJ", "cited": 2050, "abstract": "Overemphasis on hypothesis testing--and the use of P values to dichotomise significant or non-significant results--has detracted from more useful approaches to interpreting study results, such as estimation and confidence intervals. In medical studies investigators are usually interested in determining the size of difference of a measured outcome between groups, rather than a simple indication of whether or not it is statistically significant. Confidence intervals present a range of values, on the basis of the sample data, in which the population value for such a difference may lie. Some methods of calculating confidence intervals for means and differences between means are given, with similar information for proportions. The paper also gives suggestions for graphical display. Confidence i", "oa": true, "pdf_url": "https://www.bmj.com/content/bmj/292/6522/746.full.pdf", "local_pdf": "", "api": ""}, {"title": "Sparse and Compositionally Robust Inference of Microbial Ecological Networks", "doi": "https://doi.org/10.1371/journal.pcbi.1004226", "year": 2015, "authors": ["Zachary Kurtz", "Christian L. Müller", "Emily R. Miraldi", "Dan R. Littman", "Martin J. Blaser", "Richard Bonneau"], "source": "PLoS Computational Biology", "cited": 1951, "abstract": "16S ribosomal RNA (rRNA) gene and other environmental sequencing techniques provide snapshots of microbial communities, revealing phylogeny and the abundances of microbial populations across diverse ecosystems. While changes in microbial community structure are demonstrably associated with certain environmental conditions (from metabolic and immunological health in mammals to ecological stability in soils and oceans), identification of underlying mechanisms requires new statistical tools, as these datasets present several technical challenges. First, the abundances of microbial operational taxonomic units (OTUs) from amplicon-based datasets are compositional. Counts are normalized to the total number of counts in the sample. Thus, microbial abundances are not independent, and traditional s", "oa": true, "pdf_url": "https://journals.plos.org/ploscompbiol/article/file?id=10.1371/journal.pcbi.1004226&type=printable", "local_pdf": "032_Sparse and Compositionally Robust Infere.pdf", "api": ""}, {"title": "The Future of Data Analysis", "doi": "https://doi.org/10.1214/aoms/1177704711", "year": 1962, "authors": ["John W. Tukey"], "source": "The Annals of Mathematical Statistics", "cited": 1889, "abstract": "For a long time I have thought I was a statistician, interested in inferences from the particular to the general. But as I have watched mathematical statistics evolve, I have had cause to wonder and to doubt. And when I have pondered about why such techniques as the spectrum analysis of time series have proved so useful, it has become clear that their “dealing with fluctuations” aspects are, in many circumstances, of lesser importance than the aspects that would already have been required to deal effectively with the simpler case of very extensive data, where fluctuations would no longer be a problem. All in all, I have come to feel that my central interest is in data analysis, which I take to include, among other things: procedures for analyzing data, techniques for interpreting the resul", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-mathematical-statistics/volume-33/issue-1/The-Future-of-Data-Analysis/10.1214/aoms/1177704711.pdf", "local_pdf": "", "api": ""}, {"title": "Bayesian inference for psychology. Part II: Example applications with JASP", "doi": "https://doi.org/10.3758/s13423-017-1323-7", "year": 2017, "authors": ["Eric‐Jan Wagenmakers", "Jonathon Love", "Maarten Marsman", "Tahira Jamil", "Alexander Ly", "Josine Verhagen"], "source": "Psychonomic Bulletin & Review", "cited": 1837, "abstract": "Bayesian hypothesis testing presents an attractive alternative to p value hypothesis testing. Part I of this series outlined several advantages of Bayesian hypothesis testing, including the ability to quantify evidence and the ability to monitor and update this evidence as data come in, without the need to know the intention with which the data were collected. Despite these and other practical advantages, Bayesian hypothesis tests are still reported relatively rarely. An important impediment to the widespread adoption of Bayesian tests is arguably the lack of user-friendly software for the run-of-the-mill statistical problems that confront psychologists for the analysis of almost every experiment: the t-test, ANOVA, correlation, regression, and contingency tables. In Part II of this series", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.3758/s13423-017-1323-7.pdf", "local_pdf": "034_Bayesian inference for psychology. Part .pdf", "api": ""}, {"title": "Homo Heuristicus: Why Biased Minds Make Better Inferences", "doi": "https://doi.org/10.1111/j.1756-8765.2008.01006.x", "year": 2009, "authors": ["Gerd Gigerenzer", "Henry Brighton"], "source": "Topics in Cognitive Science", "cited": 1826, "abstract": "Heuristics are efficient cognitive processes that ignore information. In contrast to the widely held view that less processing reduces accuracy, the study of heuristics shows that less information, computation, and time can in fact improve accuracy. We review the major progress made so far: (a) the discovery of less-is-more effects; (b) the study of the ecological rationality of heuristics, which examines in which environments a given strategy succeeds or fails, and why; (c) an advancement from vague labels to computational models of heuristics; (d) the development of a systematic theory of heuristics that identifies their building blocks and the evolved capacities they exploit, and views the cognitive system as relying on an \"adaptive toolbox;\" and (e) the development of an empirical meth", "oa": true, "pdf_url": "https://onlinelibrary.wiley.com/doi/pdfdirect/10.1111/j.1756-8765.2008.01006.x", "local_pdf": "", "api": ""}, {"title": "Wisdom of crowds for robust gene network inference", "doi": "https://doi.org/10.1038/nmeth.2016", "year": 2012, "authors": ["Daniel Marbach", "James C. Costello", "Robert Küffner", "Nic M. Vega", "Robert J. Prill", "Diogo M. Camacho"], "source": "Nature Methods", "cited": 1800, "abstract": "", "oa": true, "pdf_url": "https://www.nature.com/articles/nmeth.2016.pdf", "local_pdf": "", "api": ""}, {"title": "On the Application of Probability Theory to Agricultural Experiments. Essay on Principles. Section 9", "doi": "https://doi.org/10.1214/ss/1177012031", "year": 1990, "authors": ["Jerzy Splawa-Neyman", "D. M. Dabrowska", "Terence P. Speed"], "source": "Statistical Science", "cited": 1670, "abstract": "In the portion of the paper translated here, Neyman introduces a model for the analysis of field experiments conducted for the purpose of comparing a number of crop varieties, which makes use of a double-indexed array of unknown potential yields, one index corresponding to varieties and the other to plots. The yield corresponding to only one variety will be observed on any given plot, but through an urn model embodying sampling without replacement from this doubly indexed array, Neyman obtains a formula for the variance of the difference between the averages of the observed yields of two varieties. This variance involves the variance over all plots of the potential yields and the correlation coefficient $r$ between the potential yields of the two varieties on the same plot. Since it is imp", "oa": true, "pdf_url": "https://projecteuclid.org/journals/statistical-science/volume-5/issue-4/On-the-Application-of-Probability-Theory-to-Agricultural-Experiments-Essay/10.1214/ss/1177012031.pdf", "local_pdf": "", "api": ""}, {"title": "On the mathematical foundations of learning", "doi": "https://doi.org/10.1090/s0273-0979-01-00923-5", "year": 2001, "authors": ["Felipe Cucker", "Steve Smale"], "source": "Bulletin of the American Mathematical Society", "cited": 1596, "abstract": "The problem of learning is arguably at the very core of the problem of intelligence, both biological and artificial.", "oa": true, "pdf_url": "https://www.ams.org/bull/2002-39-01/S0273-0979-01-00923-5/S0273-0979-01-00923-5.pdf", "local_pdf": "", "api": ""}, {"title": "Hierarchical Bayesian inference in the visual cortex", "doi": "https://doi.org/10.1364/josaa.20.001434", "year": 2003, "authors": ["Tai Sing Lee", "David B. Mumford"], "source": "Journal of the Optical Society of America A", "cited": 1549, "abstract": "Traditional views of visual processing suggest that early visual neurons in areas V1 and V2 are static spatiotemporal filters that extract local features from a visual scene. The extracted information is then channeled through a feedforward chain of modules in successively higher visual areas for further analysis. Recent electrophysiological recordings from early visual neurons in awake behaving monkeys reveal that there are many levels of complexity in the information processing of the early visual cortex, as seen in the long-latency responses of its neurons. These new findings suggest that activity in the early visual cortex is tightly coupled and highly interactive with the rest of the visual system. They lead us to propose a new theoretical setting based on the mathematical framework o", "oa": true, "pdf_url": "https://opg.optica.org/viewmedia.cfm?uri=josaa-20-7-1434&seq=0", "local_pdf": "", "api": ""}, {"title": "Statistics versus machine learning", "doi": "https://doi.org/10.1038/nmeth.4642", "year": 2018, "authors": ["Danilo Bzdok", "Naomi Altman", "Martin Krzywinski"], "source": "Nature Methods", "cited": 1540, "abstract": "", "oa": true, "pdf_url": "https://www.nature.com/articles/nmeth.4642.pdf", "local_pdf": "", "api": ""}, {"title": "Strong Control, Conservative Point Estimation and Simultaneous Conservative Consistency of False Discovery Rates: A Unified Approach", "doi": "https://doi.org/10.1111/j.1467-9868.2004.00439.x", "year": 2003, "authors": ["John D. Storey", "Jonathan Taylor", "David Siegmund"], "source": "Journal of the Royal Statistical Society Series B (Statistical Methodology)", "cited": 1451, "abstract": "Summary The false discovery rate (FDR) is a multiple hypothesis testing quantity that describes the expected proportion of false positive results among all rejected null hypotheses. Benjamini and Hochberg introduced this quantity and proved that a particular step-up p-value method controls the FDR. Storey introduced a point estimate of the FDR for fixed significance regions. The former approach conservatively controls the FDR at a fixed predetermined level, and the latter provides a conservatively biased estimate of the FDR for a fixed predetermined significance region. In this work, we show in both finite sample and asymptotic settings that the goals of the two approaches are essentially equivalent. In particular, the FDR point estimates can be used to define valid FDR controlling procedu", "oa": true, "pdf_url": "https://academic.oup.com/jrsssb/article-pdf/66/1/187/49727331/jrsssb_66_1_187.pdf", "local_pdf": "", "api": ""}, {"title": "A CENTRAL LIMIT THEOREM AND A STRONG MIXING CONDITION", "doi": "https://doi.org/10.1073/pnas.42.1.43", "year": 1956, "authors": ["M. Rosenblatt"], "source": "Proceedings of the National Academy of Sciences", "cited": 1395, "abstract": "* research for this paper was supported by the United States Air Force under Contract No. AF18(600-685) monitored by the Office of Scientific Research. 1 A discussion of the problem along with the necessary references will be found in Harry Pollard, The Harmonic Analysis of Bounded Functions, Duke Math. / . , 20, 499-512, 1953. 2 See ibid. 3 See S. Bochner, Fouriersche Integrate (Leipzig, 1932), p. 33. 4 Levitan polynomial. See N.I. Achieser, Approximationstheorie (Berlin, 1953), p. 146.", "oa": true, "pdf_url": "https://doi.org/10.1073/pnas.42.1.43", "local_pdf": "", "api": ""}, {"title": "The Bayesian New Statistics: Hypothesis testing, estimation, meta-analysis, and power analysis from a Bayesian perspective", "doi": "https://doi.org/10.3758/s13423-016-1221-4", "year": 2017, "authors": ["John K. Kruschke", "Torrin M. Liddell"], "source": "Psychonomic Bulletin & Review", "cited": 1384, "abstract": "", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.3758/s13423-016-1221-4.pdf", "local_pdf": "", "api": ""}, {"title": "SUN: A Bayesian framework for saliency using natural statistics", "doi": "https://doi.org/10.1167/8.7.32", "year": 2008, "authors": ["Lingyun Zhang", "Matthew H. Tong", "Tim K. Marks", "Honghao Shan", "Garrison W. Cottrell"], "source": "Journal of Vision", "cited": 1237, "abstract": "We propose a definition of saliency by considering what the visual system is trying to optimize when directing attention. The resulting model is a Bayesian framework from which bottom-up saliency emerges naturally as the self-information of visual features, and overall saliency (incorporating top-down information with bottom-up saliency) emerges as the pointwise mutual information between the features and the target when searching for a target. An implementation of our framework demonstrates that our model's bottom-up saliency maps perform as well as or better than existing algorithms in predicting people's fixations in free viewing. Unlike existing saliency measures, which depend on the statistics of the particular image being viewed, our measure of saliency is derived from natural image ", "oa": true, "pdf_url": "https://doi.org/10.1167/8.7.32", "local_pdf": "", "api": ""}, {"title": "Active Inference: A Process Theory", "doi": "https://doi.org/10.1162/neco_a_00912", "year": 2016, "authors": ["Karl Friston", "Thomas H. B. FitzGerald", "Francesco Rigoli", "Philipp Schwartenbeck", "Giovanni Pezzulo"], "source": "Neural Computation", "cited": 1224, "abstract": "This article describes a process theory based on active inference and belief propagation. Starting from the premise that all neuronal processing (and action selection) can be explained by maximizing Bayesian model evidence-or minimizing variational free energy-we ask whether neuronal responses can be described as a gradient descent on variational free energy. Using a standard (Markov decision process) generative model, we derive the neuronal dynamics implicit in this description and reproduce a remarkable range of well-characterized neuronal phenomena. These include repetition suppression, mismatch negativity, violation responses, place-cell activity, phase precession, theta sequences, theta-gamma coupling, evidence accumulation, race-to-bound dynamics, and transfer of dopamine responses. ", "oa": true, "pdf_url": "https://doi.org/10.1162/neco_a_00912", "local_pdf": "", "api": ""}, {"title": "Dynamic Ideal Point Estimation via Markov Chain Monte Carlo for the U.S. Supreme Court, 1953–1999", "doi": "https://doi.org/10.1093/pan/10.2.134", "year": 2002, "authors": ["Andrew D. Martin", "Kevin M. Quinn"], "source": "Political Analysis", "cited": 1186, "abstract": "At the heart of attitudinal and strategic explanations of judicial behavior is the assumption that justices have policy preferences. In this paper we employ Markov chain Monte Carlo methods to fit a Bayesian measurement model of ideal points for all justices serving on the U.S. Supreme Court from 1953 through 1999. We are particularly interested in determining to what extent ideal points of justices change throughout their tenure on the Court. This is important because judicial politics scholars oftentimes invoke preference measures that are time invariant. To investigate preference change, we posit a dynamic item response model that allows ideal points to change systematically over time. Additionally, we introduce Bayesian methods for fitting multivariate dynamic linear models to politica", "oa": true, "pdf_url": "https://www.cambridge.org/core/services/aop-cambridge-core/content/view/2A57930D5D0C81216491B40CA2BA5D12/S1047198700009931a.pdf/div-class-title-dynamic-ideal-point-estimation-via-markov-chain-monte-carlo-for-the-u-s-supreme-court-1953-1999-div.pdf", "local_pdf": "", "api": ""}, {"title": "Wilcoxon-Mann-Whitney or t-test? On assumptions for hypothesis tests and multiple interpretations of decision rules", "doi": "https://doi.org/10.1214/09-ss051", "year": 2010, "authors": ["Michael P. Fay", "Michael A. Proschan"], "source": "Statistics Surveys", "cited": 1141, "abstract": "In a mathematical approach to hypothesis tests, we start with a clearly defined set of hypotheses and choose the test with the best properties for those hypotheses. In practice, we often start with less precise hypotheses. For example, often a researcher wants to know which of two groups generally has the larger responses, and either a t-test or a Wilcoxon-Mann-Whitney (WMW) test could be acceptable. Although both t-tests and WMW tests are usually associated with quite different hypotheses, the decision rule and p-value from either test could be associated with many different sets of assumptions, which we call perspectives. It is useful to have many of the different perspectives to which a decision rule may be applied collected in one place, since each perspective allows a different interp", "oa": true, "pdf_url": "https://projecteuclid.org/journals/statistics-surveys/volume-4/issue-none/Wilcoxon-Mann-Whitney-or-t-test-On-assumptions-for-hypothesis/10.1214/09-SS051.pdf", "local_pdf": "", "api": ""}, {"title": "Multiple Hypothesis Testing in Microarray Experiments", "doi": "https://doi.org/10.1214/ss/1056397487", "year": 2003, "authors": ["Sandrine Dudoit", "Juliet Popper Shaffer", "Jennifer C. Boldrick"], "source": "Statistical Science", "cited": 1098, "abstract": "DNA microarrays are part of a new and promising class of biotechnologies that allow the monitoring of expression levels in cells for thousands of genes simultaneously. An important and common question in DNA microarray experiments is the identification of differentially expressed genes, that is, genes whose expression levels are associated with a response or covariate of interest. The biological question of differential expression can be restated as a problem in multiple hypothesis testing: the simultaneous test for each gene of the null hypothesis of no association between the expression levels and the responses or covariates. As a typical microarray experiment measures expression levels for thousands of genes simultaneously, large multiplicity problems are generated. This article discuss", "oa": true, "pdf_url": "https://projecteuclid.org/journals/statistical-science/volume-18/issue-1/Multiple-Hypothesis-Testing-in-Microarray-Experiments/10.1214/ss/1056397487.pdf", "local_pdf": "", "api": ""}, {"title": "Central limit theorem: the cornerstone of modern statistics", "doi": "https://doi.org/10.4097/kjae.2017.70.2.144", "year": 2017, "authors": ["Sang Gyu Kwak", "Jonghae Kim"], "source": "Korean Journal of Anesthesiology", "cited": 1072, "abstract": ", distribute normally with mean, µ, and variance, [Formula: see text]. Using the central limit theorem, a variety of parametric tests have been developed under assumptions about the parameters that determine the population probability distribution. Compared to non-parametric tests, which do not require any assumptions about the population probability distribution, parametric tests produce more accurate and precise estimates with higher statistical powers. However, many medical researchers use parametric tests to present their data without knowledge of the contribution of the central limit theorem to the development of such tests. Thus, this review presents the basic concepts of the central limit theorem and its role in binomial distributions and the Student's t-test, and provides an exampl", "oa": true, "pdf_url": "https://doi.org/10.4097/kjae.2017.70.2.144", "local_pdf": "", "api": ""}, {"title": "Bayesian Versus Orthodox Statistics: Which Side Are You On?", "doi": "https://doi.org/10.1177/1745691611406920", "year": 2011, "authors": ["Zoltán Dienes"], "source": "Perspectives on Psychological Science", "cited": 993, "abstract": "Researchers are often confused about what can be inferred from significance tests. One problem occurs when people apply Bayesian intuitions to significance testing-two approaches that must be firmly separated. This article presents some common situations in which the approaches come to different conclusions; you can see where your intuitions initially lie. The situations include multiple testing, deciding when to stop running participants, and when a theory was thought of relative to finding out results. The interpretation of nonsignificant results has also been persistently problematic in a way that Bayesian inference can clarify. The Bayesian and orthodox approaches are placed in the context of different notions of rationality, and I accuse myself and others as having been irrational in ", "oa": true, "pdf_url": "https://doi.org/10.1177/1745691611406920", "local_pdf": "", "api": ""}, {"title": "Birds of the Same Feather Tweet Together: Bayesian Ideal Point Estimation Using Twitter Data", "doi": "https://doi.org/10.1093/pan/mpu011", "year": 2014, "authors": ["Pablo Barberá"], "source": "Political Analysis", "cited": 992, "abstract": "Politicians and citizens increasingly engage in political conversations on social media outlets such as Twitter. In this article, I show that the structure of the social networks in which they are embedded can be a source of information about their ideological positions. Under the assumption that social networks are homophilic, I develop a Bayesian Spatial Following model that considers ideology as a latent variable, whose value can be inferred by examining which politics actors each user is following. This method allows us to estimate ideology for more actors than any existing alternative, at any point in time and across many polities. I apply this method to estimate ideal points for a large sample of both elite and mass public Twitter users in the United States and five European countrie", "oa": true, "pdf_url": "https://www.cambridge.org/core/services/aop-cambridge-core/content/view/91E37205F69AEA32EF27F12563DC2A0A/S104719870001161Xa.pdf/div-class-title-birds-of-the-same-feather-tweet-together-bayesian-ideal-point-estimation-using-twitter-data-div.pdf", "local_pdf": "", "api": ""}, {"title": "Robust performance hypothesis testing with the Sharpe ratio", "doi": "https://doi.org/10.1016/j.jempfin.2008.03.002", "year": 2008, "authors": ["Oliver Ledoit", "Michael Wolf"], "source": "Journal of Empirical Finance", "cited": 985, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1016/j.jempfin.2008.03.002", "local_pdf": "", "api": ""}, {"title": "Estimation of the point of zero charge of simple oxides by mass titration", "doi": "https://doi.org/10.1016/0021-9797(89)90086-6", "year": 1989, "authors": ["Joong S Noh", "J.A. Schwarz"], "source": "Journal of Colloid and Interface Science", "cited": 908, "abstract": "A method is proposed to estimate the point of zero charge (pzc) of pure compounds which can be described accurately by the surface ionization model of amphoteric oxides. It is demonstrated that under the limiting conditions of “infinite” mass/volume ratio, the pH of the system will approach pH∞ = 12(pK1 + pK2)  pzc. Experimental values of the pH of the oxides of titanium, aluminum, a silicon suspended in a closed aqueous system exhibited the existence of a constant pH at high mass fractions. This limiting pH is found to be a reasonable estimate for the point of zero charge of each oxide.", "oa": true, "pdf_url": "https://doi.org/10.1016/0021-9797(89)90086-6", "local_pdf": "", "api": ""}, {"title": "Mathematical Statistics and Data Analysis", "doi": "https://doi.org/10.2307/1269179", "year": 1995, "authors": ["Eric R. Ziegel", "John Rice"], "source": "Technometrics", "cited": 844, "abstract": "Concluding Remarks p.Problems p.", "oa": true, "pdf_url": "https://www.jstor.org/institutionSearch?redirectUri=%2fstable%2f1269179", "local_pdf": "", "api": ""}, {"title": "Hypothesis Testing and Multiplicative Interaction Terms", "doi": "https://doi.org/10.1017/s0020818304040251", "year": 2004, "authors": ["Bear Braumoeller"], "source": "International Organization", "cited": 832, "abstract": "When a statistical equation incorporates a multiplicative term in an attempt to model interaction effects, the statistical significance of the lower-order coefficients is largely useless for the typical purposes of hypothesis testing. This fact remains largely unappreciated in political science, however. This brief article explains this point, provides examples, and offers some suggestions for more meaningful interpretation.", "oa": true, "pdf_url": "https://www.cambridge.org/core/services/aop-cambridge-core/content/view/5AE39EABAA8F26582C65F0D3FAD153D8/S0020818304040251a.pdf/div-class-title-hypothesis-testing-and-multiplicative-interaction-terms-div.pdf", "local_pdf": "", "api": ""}, {"title": "HyPhy 2.5—A Customizable Platform for Evolutionary Hypothesis Testing Using Phylogenies", "doi": "https://doi.org/10.1093/molbev/msz197", "year": 2019, "authors": ["Sergei L. Kosakovsky Pond", "Art F. Y. Poon", "Ryan Velazquez", "Steven Weaver", "N. Lance Hepler", "Ben Murrell"], "source": "Molecular Biology and Evolution", "cited": 822, "abstract": "HYpothesis testing using PHYlogenies (HyPhy) is a scriptable, open-source package for fitting a broad range of evolutionary models to multiple sequence alignments, and for conducting subsequent parameter estimation and hypothesis testing, primarily in the maximum likelihood statistical framework. It has become a popular choice for characterizing various aspects of the evolutionary process: natural selection, evolutionary rates, recombination, and coevolution. The 2.5 release (available from www.hyphy.org) includes a completely re-engineered computational core and analysis library that introduces new classes of evolutionary models and statistical tests, delivers substantial performance and stability enhancements, improves usability, streamlines end-to-end analysis workflows, makes it easier", "oa": true, "pdf_url": "https://doi.org/10.1093/molbev/msz197", "local_pdf": "", "api": ""}, {"title": "Bayesian hypothesis testing for psychologists: A tutorial on the Savage–Dickey method", "doi": "https://doi.org/10.1016/j.cogpsych.2009.12.001", "year": 2010, "authors": ["Eric‐Jan Wagenmakers", "Tom Lodewyckx", "Himanshu Kuriyal", "Raoul P. P. P. Grasman"], "source": "Cognitive Psychology", "cited": 805, "abstract": "", "oa": true, "pdf_url": "https://www.sciencedirect.com/science/article/pii/S0010028509000826", "local_pdf": "", "api": ""}, {"title": "Rapid Hypothesis Testing with Candida albicans through Gene Disruption with Short Homology Regions", "doi": "https://doi.org/10.1128/jb.181.6.1868-1874.1999", "year": 1999, "authors": ["R. Bryce Wilson", "Dana A. Davis", "Aaron P. Mitchell"], "source": "Journal of Bacteriology", "cited": 769, "abstract": "Disruption of newly identified genes in the pathogen Candida albicans is a vital step in determination of gene function. Several gene disruption methods described previously employ long regions of homology flanking a selectable marker. Here, we describe disruption of C. albicans genes with PCR products that have 50 to 60 bp of homology to a genomic sequence on each end of a selectable marker. We used the method to disrupt two known genes, ARG5 and ADE2, and two sequences newly identified through the Candida genome project, HRM101 and ENX3. HRM101 and ENX3 are homologous to genes in the conserved RIM101 (previously called RIM1) and PacC pathways of Saccharomyces cerevisiae and Aspergillus nidulans. We show that three independent hrm101/hrm101 mutants and two independent enx3/enx3 mutants ar", "oa": true, "pdf_url": "https://doi.org/10.1128/jb.181.6.1868-1874.1999", "local_pdf": "", "api": ""}, {"title": "Simple methods for testing the molecular evolutionary clock hypothesis.", "doi": "10.1093/genetics/135.2.599", "year": 1993, "authors": ["F Tajima"], "source": "Genetics", "cited": 766, "abstract": "【Abstract】\n                   Simple statistical methods for testing the molecular evolutionary clock hypothesis are developed which can be applied to both nucleotide and amino acid sequences. These methods are based on the chi-square test and are applicable even when the pattern of substitution rates is unknown and/or the substitution rate varies among different sites. Furthermore, some of the methods can be applied even when the outgroup is unknown. Using computer simulations, these methods were compared with the likelihood ratio test and the relative rate test. The results indicate that the powers of the present methods are similar to those of the likelihood ratio test and the relative rate test, in spite of the fact that the latter two tests assume that the pattern of substitution rate", "oa": true, "pdf_url": "http://academic.oup.com/genetics/article-pdf/135/2/599/34593395/genetics0599.pdf", "local_pdf": "", "api": "crossref"}, {"title": "Counterfactuals and Hypothesis Testing in Political Science", "doi": "https://doi.org/10.2307/2010470", "year": 1991, "authors": ["James D. Fearon"], "source": "World Politics", "cited": 729, "abstract": "Scholars in comparative politics and international relations routinely evaluate causal hypotheses by referring tocounterfactual caseswhere a hypothesized causal factor is supposed to have been absent. The methodological status and the viability of this very common procedure are unclear and are worth examining. How does the strategy of counterfactual argument relate, if at all, to methods of hypothesis testing based on the comparison of actual cases, such as regression analysis or Mill's Method of Difference? Are counterfactual thought experiments a viable means of assessing hypotheses about national and international outcomes, or are they methodologically invalid in principle? The paper addresses the first question in some detail and begins discussion of the second. Examples from work on t", "oa": true, "pdf_url": "https://doi.org/10.2307/2010470", "local_pdf": "", "api": ""}, {"title": "Determination of absolute structure using Bayesian statistics on Bijvoet differences", "doi": "https://doi.org/10.1107/s0021889807059870", "year": 2008, "authors": ["Rob Hooft", "L. Straver", "Anthony L. Spek"], "source": "Journal of Applied Crystallography", "cited": 725, "abstract": "A new probabilistic approach is introduced for the determination of the absolute structure of a compound which is known to be enantiopure based on Bijvoet-pair intensity differences. The new method provides relative probabilities for different models of the chiral composition of the structure. The outcome of this type of analysis can also be cast in the form of a new value, along with associated standard uncertainty, that resembles the value of the well known Flack x parameter. The standard uncertainty we obtain is often about half of the standard uncertainty in the value of the Flack x parameter. The proposed formalism is suited in particular to absolute configuration determination from diffraction data of biologically active (pharmaceutical) compounds where the strongest resonant scatter", "oa": true, "pdf_url": "http://journals.iucr.org/j/issues/2008/01/00/ks5161/ks5161.pdf", "local_pdf": "", "api": ""}, {"title": "Martingale Central Limit Theorems", "doi": "https://doi.org/10.1214/aoms/1177693494", "year": 1971, "authors": ["B. M. Brown"], "source": "The Annals of Mathematical Statistics", "cited": 719, "abstract": "The classical Lindeberg-Feller CLT for sums of independent random variables (rv's) provides more than the convergence in distribution of the sum to a normal law. The independence of summands also guarantees the weak convergence of all finite dimensional distributions of an a.e. sample continuous stochastic process (suitably defined in terms of the partial sums) to those of a Gaussian process with independent increments, namely, the Wiener process. Moreover, the distributions of said process converge weakly to Wiener measure on $C\\lbrack 0, 1\\rbrack$, the latter result being known as an invariance principle, or functional CLT, an idea originating with Erdos and Kac [10] and Donsker [5], then developed by Billingsley, Prohorov, Skorohod and others. The present work contains an invariance pri", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-mathematical-statistics/volume-42/issue-1/Martingale-Central-Limit-Theorems/10.1214/aoms/1177693494.pdf", "local_pdf": "", "api": ""}, {"title": "Using Bayes factor hypothesis testing in neuroscience to establish evidence of absence", "doi": "https://doi.org/10.1038/s41593-020-0660-4", "year": 2020, "authors": ["Christian Keysers", "Valeria Gazzola", "Eric‐Jan Wagenmakers"], "source": "Nature Neuroscience", "cited": 718, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1038/s41593-020-0660-4", "local_pdf": "", "api": ""}, {"title": "Convergence of Random Processes and Limit Theorems in Probability Theory", "doi": "10.1137/1101016", "year": 1956, "authors": ["Yu. V. Prokhorov"], "source": "Theory of Probability &amp; Its Applications", "cited": 707, "abstract": " The convergence of stochastic processes is defined in terms of the so-called “weak convergence” (w. c.) of probability measures in appropriate functional spaces (c. s. m. s.). \n                   Chapter 1. Let $\\Re $ be the c.s.m.s. and v a set of all finite measures on $\\Re $. The distance $L(\\mu _1 ,\\mu _2 )$ (that is analogous to the Lévy distance) is introduced, and equivalence of L-convergence and w. c. is proved. It is shown that $V\\Re = (v,L)$ is c. s. m. s. Then, the necessary and sufficient conditions for compactness in $V\\Re $ are given. \n                   In section 1.6 the concept of “characteristic functionals” is applied to the study of w. cc of measures in Hilbert space. \n                   Chapter 2. On the basis of the above results the necessary and sufficient compactn", "oa": false, "pdf_url": "", "local_pdf": "", "api": "crossref"}, {"title": "[On the Application of Probability Theory to Agricultural Experiments. Essay on Principles. Section 9.] Comment: Neyman (1923) and Causal Inference in Experiments and Observational Studies", "doi": "https://doi.org/10.1214/ss/1177012032", "year": 1990, "authors": ["Donald B. Rubin"], "source": "Statistical Science", "cited": 663, "abstract": "", "oa": true, "pdf_url": "https://projecteuclid.org/journals/statistical-science/volume-5/issue-4/On-the-Application-of-Probability-Theory-to-Agricultural-Experiments-Essay/10.1214/ss/1177012032.pdf", "local_pdf": "", "api": ""}, {"title": "Philosophy and the practice of Bayesian statistics", "doi": "https://doi.org/10.1111/j.2044-8317.2011.02037.x", "year": 2012, "authors": ["Andrew Gelman", "Cosma Rohilla Shalizi"], "source": "British Journal of Mathematical and Statistical Psychology", "cited": 624, "abstract": "A substantial school in the philosophy of science identifies Bayesian inference with inductive inference and even rationality as such, and seems to be strengthened by the rise and practical success of Bayesian statistics. We argue that the most successful forms of Bayesian statistics do not actually support that particular philosophy but rather accord much better with sophisticated forms of hypothetico-deductivism. We examine the actual role played by prior distributions in Bayesian models, and the crucial aspects of model checking and model revision, which fall outside the scope of Bayesian confirmation theory. We draw on the literature on the consistency of Bayesian updating and also on our experience of applied work in social science. Clarity about these matters should benefit not just ", "oa": true, "pdf_url": "https://doi.org/10.1111/j.2044-8317.2011.02037.x", "local_pdf": "", "api": ""}, {"title": "Non-central limit theorems for non-linear functional of Gaussian fields", "doi": "https://doi.org/10.1007/bf00535673", "year": 1979, "authors": ["R. L. Dobrushin", "Péter Major"], "source": "Probability Theory and Related Fields", "cited": 618, "abstract": "", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.1007/BF00535673.pdf", "local_pdf": "", "api": ""}, {"title": "Graph Theory and Probability", "doi": "https://doi.org/10.4153/cjm-1959-003-9", "year": 1959, "authors": ["Paul Erdős"], "source": "Canadian Journal of Mathematics", "cited": 602, "abstract": "A well-known theorem of Ramsay (8; 9) states that to every n there exists a smallest integer g(n) so that every graph of g(n) vertices contains either a set of n independent points or a complete graph of order n , but there exists a graph of g(n) — 1 vertices which does not contain a complete subgraph of n vertices and also does not contain a set of n independent points. (A graph is called complete if every two of its vertices are connected by an edge; a set of points is called independent if no two of its points are connected by an edge.) The determination of g(n) seems a very difficult problem; the best inequalities for g(n) are (3) It is not even known that g(n) 1/n tends to a limit. The lower bound in (1) has been obtained by combinatorial and probabilistic arguments without an explici", "oa": true, "pdf_url": "https://www.cambridge.org/core/services/aop-cambridge-core/content/view/154EF813293BC7D0652C4CBCD9D18E84/S0008414X00002947a.pdf/div-class-title-graph-theory-and-probability-div.pdf", "local_pdf": "", "api": ""}, {"title": "Equivalence of distance-based and RKHS-based statistics in hypothesis testing", "doi": "https://doi.org/10.1214/13-aos1140", "year": 2013, "authors": ["Dino Sejdinović", "Bharath K. Sriperumbudur", "Arthur Gretton", "Kenji Fukumizu"], "source": "The Annals of Statistics", "cited": 602, "abstract": "We provide a unifying framework linking two classes of statistics used in two-sample and independence testing: on the one hand, the energy distances and distance covariances from the statistics literature; on the other, maximum mean discrepancies (MMD), that is, distances between embeddings of distributions to reproducing kernel Hilbert spaces (RKHS), as established in machine learning. In the case where the energy distance is computed with a semimetric of negative type, a positive definite kernel, termed distance kernel, may be defined such that the MMD corresponds exactly to the energy distance. Conversely, for any positive definite kernel, we can interpret the MMD as energy distance with respect to some negative-type semimetric. This equivalence readily extends to distance covariance us", "oa": true, "pdf_url": "https://doi.org/10.1214/13-aos1140", "local_pdf": "", "api": ""}, {"title": "Dependent Central Limit Theorems and Invariance Principles", "doi": "https://doi.org/10.1214/aop/1176996608", "year": 1974, "authors": ["D. L. McLeish"], "source": "The Annals of Probability", "cited": 598, "abstract": "Central limit theorems are proved for martingales and near-martingales without the existence of moments or the full Lindeberg condition. These theorems are extended to invariance principles with a discussion of both random and nonrandom norming.", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-probability/volume-2/issue-4/Dependent-Central-Limit-Theorems-and-Invariance-Principles/10.1214/aop/1176996608.pdf", "local_pdf": "", "api": ""}, {"title": "Quantum theory of probability and decisions", "doi": "https://doi.org/10.1098/rspa.1999.0443", "year": 1999, "authors": ["David Deutsch"], "source": "Proceedings of the Royal Society A Mathematical Physical and Engineering Sciences", "cited": 587, "abstract": "The probabilistic predictions of quantum theory are conventionally obtained from a special probabilistic axiom. But that is unnecessary because all the practical consequences of such predictions follow from the remaining non–probabilistic axioms of quantum theory, together with the non–probabilistic part of classical decision theory.", "oa": true, "pdf_url": "https://doi.org/10.1098/rspa.1999.0443", "local_pdf": "", "api": ""}, {"title": "Central Limit Theorems for Empirical Measures", "doi": "https://doi.org/10.1214/aop/1176995384", "year": 1978, "authors": ["R. M. Dudley"], "source": "The Annals of Probability", "cited": 584, "abstract": "Let $(X, \\mathscr{A}, P)$ be a probability space. Let $X_1, X_2,\\cdots,$ be independent $X$-valued random variables with distribution $P$. Let $P_n := n^{-1}(\\delta_{X_1} + \\cdots + \\delta_{X_n})$ be the empirical measure and let $\\nu_n := n^\\frac{1}{2}(P_n - P)$. Given a class $\\mathscr{C} \\subset \\mathscr{a}$, we study the convergence in law of $\\nu_n$, as a stochastic process indexed by $\\mathscr{C}$, to a certain Gaussian process indexed by $\\mathscr{C}$. If convergence holds with respect to the supremum norm $\\sup_{C \\in \\mathscr{C}}|f(C)|$, in a suitable (usually nonseparable) function space, we call $\\mathscr{C}$ a Donsker class. For measurability, $X$ may be a complete separable metric space, $\\mathscr{a} =$ Borel sets, and $\\mathscr{C}$ a suitable collection of closed sets or open", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-probability/volume-6/issue-6/Central-Limit-Theorems-for-Empirical-Measures/10.1214/aop/1176995384.pdf", "local_pdf": "", "api": ""}, {"title": "A default Bayesian hypothesis test for correlations and partial correlations", "doi": "https://doi.org/10.3758/s13423-012-0295-x", "year": 2012, "authors": ["Ruud Wetzels", "Eric‐Jan Wagenmakers"], "source": "Psychonomic Bulletin & Review", "cited": 550, "abstract": "We propose a default Bayesian hypothesis test for the presence of a correlation or a partial correlation. The test is a direct application of Bayesian techniques for variable selection in regression models. The test is easy to apply and yields practical advantages that the standard frequentist tests lack; in particular, the Bayesian test can quantify evidence in favor of the null hypothesis and allows researchers to monitor the test results as the data come in. We illustrate the use of the Bayesian correlation test with three examples from the psychological literature. Computer code and example data are provided in the journal archives.", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.3758%2Fs13423-012-0295-x.pdf", "local_pdf": "", "api": ""}, {"title": "Central limit theorem for integrated square error of multivariate nonparametric density estimators", "doi": "https://doi.org/10.1016/0047-259x(84)90044-7", "year": 1984, "authors": ["Peter Hall"], "source": "Journal of Multivariate Analysis", "cited": 481, "abstract": "", "oa": true, "pdf_url": "https://www.sciencedirect.com/science/article/pii/0047259X84900447/pdf", "local_pdf": "", "api": ""}, {"title": "Improving transparency and replication in Bayesian statistics: The WAMBS-Checklist.", "doi": "https://doi.org/10.1037/met0000065", "year": 2015, "authors": ["Sarah Depaoli", "Rens van de Schoot"], "source": "Psychological Methods", "cited": 460, "abstract": "Bayesian statistical methods are slowly creeping into all fields of science and are becoming ever more popular in applied research. Although it is very attractive to use Bayesian statistics, our personal experience has led us to believe that naively applying Bayesian methods can be dangerous for at least 3 main reasons: the potential influence of priors, misinterpretation of Bayesian features and results, and improper reporting of Bayesian results. To deal with these 3 points of potential danger, we have developed a succinct checklist: the WAMBS-checklist (When to worry and how to Avoid the Misuse of Bayesian Statistics). The purpose of the questionnaire is to describe 10 main points that should be thoroughly checked when applying Bayesian analysis. We provide an account of \"when to worry\"", "oa": true, "pdf_url": "https://doi.org/10.1037/met0000065", "local_pdf": "", "api": ""}, {"title": "Central limit theorems for sequences of multiple stochastic integrals", "doi": "https://doi.org/10.1214/009117904000000621", "year": 2005, "authors": ["David Nualart", "Giovanni Peccati"], "source": "The Annals of Probability", "cited": 459, "abstract": "We characterize the convergence in distribution to a standard normal law for a sequence of multiple stochastic integrals of a fixed order with variance converging to 1. Some applications are given, in particular to study the limiting behavior of quadratic functionals of Gaussian processes.", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-probability/volume-33/issue-1/Central-limit-theorems-for-sequences-of-multiple-stochastic-integrals/10.1214/009117904000000621.pdf", "local_pdf": "", "api": ""}, {"title": "Risk aversion in the theory of expected utility with rank dependent probabilities", "doi": "https://doi.org/10.1016/0022-0531(87)90093-7", "year": 1987, "authors": ["Chew Soo Hong", "Edi Karni", "Zvi Safra"], "source": "Journal of Economic Theory", "cited": 448, "abstract": "Expected utility with rank dependent probability theory is a model of decision-making under risk where the preference relations on the set of probability distributions is represented by the mathematical expectation of a utility function with respect to a transformation of the probability distributions on the set of outcomes. This paper defines, based on Gâteaux differentiability, measures of risk aversion for such preferences which characterize the relation “more risk averse” and applies these measures to the analysis of unconditional and conditional portfolio choice problems.", "oa": true, "pdf_url": "https://doi.org/10.1016/0022-0531(87)90093-7", "local_pdf": "", "api": ""}, {"title": "Missing Point Estimation in Models Described by Proper Orthogonal Decomposition", "doi": "https://doi.org/10.1109/tac.2008.2006102", "year": 2008, "authors": ["P. Astrid", "S. Weiland", "Karen Willcox", "Ton Backx"], "source": "IEEE Transactions on Automatic Control", "cited": 445, "abstract": "This paper presents a new method of missing point estimation (MPE) to derive efficient reduced-order models for large-scale parameter-varying systems. Such systems often result from the discretization of nonlinear partial differential equations. A projection-based model reduction framework is used where projection spaces are inferred from proper orthogonal decompositions of data-dependent correlation operators. The key contribution of the MPE method is to perform online computations efficiently by computing Galerkin projections over a restricted subset of the spatial domain. Quantitative criteria for optimally selecting such a spatial subset are proposed and the resulting optimization problem is solved using an efficient heuristic method. The effectiveness of the MPE method is demonstrated", "oa": true, "pdf_url": "https://doi.org/10.1109/tac.2008.2006102", "local_pdf": "", "api": ""}, {"title": "Change-point detection in time-series data by relative density-ratio estimation", "doi": "https://doi.org/10.1016/j.neunet.2013.01.012", "year": 2013, "authors": ["Song Liu", "Makoto Yamada", "Nigel Collier", "Masashi Sugiyama"], "source": "Neural Networks", "cited": 445, "abstract": "", "oa": true, "pdf_url": "https://doi.org/10.1016/j.neunet.2013.01.012", "local_pdf": "", "api": ""}, {"title": "Surrogate data for hypothesis testing of physical systems", "doi": "https://doi.org/10.1016/j.physrep.2018.06.001", "year": 2018, "authors": ["Gemma Lancaster", "Dmytro Iatsenko", "Aleksandra Pidde", "Valentina Ticcinelli", "Aneta Stefanovska"], "source": "Physics Reports", "cited": 444, "abstract": "The availability of time series of the evolution of the properties of physical systems is increasing, stimulating the development of many novel methods for the extraction of information about their behaviour over time, including whether or not they arise from deterministic or stochastic dynamical systems. Surrogate data testing is an essential part of many of these methods, as it enables robust statistical evaluations to ensure that the results observed are not obtained by chance, but are a true characteristic of the underlying system. The surrogate data technique is based on the comparison of a particular property of the data (a discriminating statistic) with the distribution of the same property calculated in a set of constructed signals (surrogates) which match the original data set but", "oa": true, "pdf_url": "https://doi.org/10.1016/j.physrep.2018.06.001", "local_pdf": "", "api": ""}, {"title": "Central limit theorem for sequential Monte Carlo methods and its application to Bayesian inference", "doi": "https://doi.org/10.1214/009053604000000698", "year": 2004, "authors": ["Nicolas Chopin"], "source": "The Annals of Statistics", "cited": 443, "abstract": "The term “sequential Monte Carlo methods” or, equivalently, “particle filters,” refers to a general class of iterative algorithms that performs Monte Carlo approximations of a given sequence of distributions of interest (πt). We establish in this paper a central limit theorem for the Monte Carlo estimates produced by these computational methods. This result holds under minimal assumptions on the distributions πt, and applies in a general framework which encompasses most of the sequential Monte Carlo methods that have been considered in the literature, including the resample-move algorithm of Gilks and Berzuini [J. R. Stat. Soc. Ser. B Stat. Methodol. 63 (2001) 127–146] and the residual resampling scheme. The corresponding asymptotic variances provide a convenient measurement of the precisi", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-statistics/volume-32/issue-6/Central-limit-theorem-for-sequential-Monte-Carlo-methods-and-its/10.1214/009053604000000698.pdf", "local_pdf": "", "api": ""}, {"title": "Optimal Inequalities in Probability Theory: A Convex Optimization Approach", "doi": "https://doi.org/10.1137/s1052623401399903", "year": 2005, "authors": ["Dimitris Bertsimas", "Ioana Popescu"], "source": "SIAM Journal on Optimization", "cited": 438, "abstract": "We propose a semidefinite optimization approach to the problem of deriving tight moment inequalities for $P(X\\in S)$, for a set S defined by polynomial inequalities and a random vector X defined on $\\Omega\\subseteq {\\cal R}^n$ that has a given collection of up to kth-order moments. In the univariate case, we provide optimal bounds on $P(X\\in S)$, when the first k moments of X are given, as the solution of a semidefinite optimization problem in k + 1 dimensions. In the multivariate case, if the sets S and $\\Omega$ are given by polynomial inequalities, we obtain an improving sequence of bounds by solving semidefinite optimization problems of polynomial size in n, for fixed k. We characterize the complexity of the problem of deriving tight moment inequalities. We show that it is NP-hard to fi", "oa": true, "pdf_url": "https://doi.org/10.1137/s1052623401399903", "local_pdf": "", "api": ""}, {"title": "Advanced Statistics: Bootstrapping Confidence Intervals for Statistics with “Difficult” Distributions", "doi": "https://doi.org/10.1197/j.aem.2004.11.018", "year": 2005, "authors": ["Jason S. Haukoos", "Roger Lewis"], "source": "Academic Emergency Medicine", "cited": 437, "abstract": "The use of confidence intervals in reporting results of research has increased dramatically and is now required or highly recommended by editors of many scientific journals. Many resources describe methods for computing confidence intervals for statistics with mathematically simple distributions. Computing confidence intervals for descriptive statistics with distributions that are difficult to represent mathematically is more challenging. The bootstrap is a computationally intensive statistical technique that allows the researcher to make inferences from data without making strong distributional assumptions about the data or the statistic being calculated. This allows the researcher to estimate confidence intervals for statistics that do not have simple sampling distributions (e.g., the me", "oa": true, "pdf_url": "https://onlinelibrary.wiley.com/doi/pdfdirect/10.1197/j.aem.2004.11.018", "local_pdf": "", "api": ""}, {"title": "Hypothesis testing, type I and type II errors", "doi": "https://doi.org/10.4103/0972-6748.62274", "year": 2009, "authors": ["Banerjee Ak", "UB Chitnis", "Sudhir Jadhav", "JS Bhawalkar", "Suprakash Chaudhury"], "source": "Industrial Psychiatry Journal", "cited": 437, "abstract": "Hypothesis testing is an important activity of empirical research and evidence-based medicine. A well worked up hypothesis is half the answer to the research question. For this, both knowledge of the subject derived from extensive review of the literature and working knowledge of basic statistical concepts are desirable. The present paper discusses the methods of working up a good hypothesis and statistical concepts of hypothesis testing.", "oa": true, "pdf_url": "https://doi.org/10.4103/0972-6748.62274", "local_pdf": "", "api": ""}, {"title": "Attention and Conscious Perception in the Hypothesis Testing Brain", "doi": "https://doi.org/10.3389/fpsyg.2012.00096", "year": 2012, "authors": ["Jakob Hohwy"], "source": "Frontiers in Psychology", "cited": 426, "abstract": "Conscious perception and attention are difficult to study, partly because their relation to each other is not fully understood. Rather than conceiving and studying them in isolation from each other it may be useful to locate them in an independently motivated, general framework, from which a principled account of how they relate can then emerge. Accordingly, these mental phenomena are here reviewed through the prism of the increasingly influential predictive coding framework. On this framework, conscious perception can be seen as the upshot of prediction error minimization and attention as the optimization of precision expectations during such perceptual inference. This approach maps on well to a range of standard characteristics of conscious perception and attention, and can be used to in", "oa": true, "pdf_url": "https://www.frontiersin.org/articles/10.3389/fpsyg.2012.00096/pdf", "local_pdf": "", "api": ""}, {"title": "A Modern Approach to Probability Theory", "doi": "https://doi.org/10.1007/978-1-4899-2837-5", "year": 1997, "authors": ["Bert Fristedt", "Lawrence Gray"], "source": "Birkhäuser Boston eBooks", "cited": 403, "abstract": "Overview This book is intended as a textbook in probability for graduate students in math ematics and related areas such as statistics, economics, physics, and operations research. Probability theory", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.1007/978-1-4899-2837-5.pdf", "local_pdf": "", "api": ""}, {"title": "Entropy and the Central Limit Theorem", "doi": "https://doi.org/10.1214/aop/1176992632", "year": 1986, "authors": ["Andrew R. Barron"], "source": "The Annals of Probability", "cited": 375, "abstract": "A strengthened central limit theorem for densities is established showing monotone convergence in the sense of relative entropy.", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-probability/volume-14/issue-1/Entropy-and-the-Central-Limit-Theorem/10.1214/aop/1176992632.pdf", "local_pdf": "", "api": ""}, {"title": "On the Markov chain central limit theorem", "doi": "https://doi.org/10.1214/154957804100000051", "year": 2004, "authors": ["Galin L. Jones"], "source": "Probability Surveys", "cited": 375, "abstract": "The goal of this expository paper is to describe conditions which guarantee a central limit theorem for functionals of general state space Markov chains. This is done with a view towards Markov chain Monte Carlo settings and hence the focus is on the connections between drift and mixing conditions and their implications. In particular, we consider three commonly cited central limit theorems and discuss their relationship to classical results for mixing processes. Several motivating examples are given which range from toy one-dimensional settings to complicated settings encountered in Markov chain Monte Carlo.", "oa": true, "pdf_url": "https://projecteuclid.org/journals/probability-surveys/volume-1/issue-none/On-the-Markov-chain-central-limit-theorem/10.1214/154957804100000051.pdf", "local_pdf": "", "api": ""}, {"title": "A central limit theorem for generalized quadratic forms", "doi": "https://doi.org/10.1007/bf00354037", "year": 1987, "authors": ["Peter de Jong"], "source": "Probability Theory and Related Fields", "cited": 372, "abstract": "", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.1007/BF00354037.pdf", "local_pdf": "", "api": ""}, {"title": "An Introduction to Bayesian Hypothesis Testing for Management Research", "doi": "https://doi.org/10.1177/0149206314560412", "year": 2014, "authors": ["Sandra Andraszewicz", "Benjamin Scheibehenne", "Jörg Rieskamp", "Raoul P. P. P. Grasman", "Josine Verhagen", "Eric‐Jan Wagenmakers"], "source": "Journal of Management", "cited": 370, "abstract": "In management research, empirical data are often analyzed using p-value null hypothesis significance testing (pNHST). Here we outline the conceptual and practical advantages of an alternative analysis method: Bayesian hypothesis testing and model selection using the Bayes factor. In contrast to pNHST, Bayes factors allow researchers to quantify evidence in favor of the null hypothesis. Also, Bayes factors do not require adjustment for the intention with which the data were collected. The use of Bayes factors is demonstrated through an extended example for hierarchical regression based on the design of an experiment recently published in the Journal of Management. This example also highlights the fact that p values overestimate the evidence against the null hypothesis, misleading researcher", "oa": true, "pdf_url": "https://doi.org/10.1177/0149206314560412", "local_pdf": "", "api": ""}, {"title": "Information theory and hypothesis testing: a call for pluralism", "doi": "https://doi.org/10.1111/j.1365-2664.2005.01002.x", "year": 2005, "authors": ["Philip A. Stephens", "Steven W. Buskirk", "Gregory D. Hayward", "Carlos Martı́nez del Rio"], "source": "Journal of Applied Ecology", "cited": 365, "abstract": "Summary A major paradigm shift is occurring in the approach of ecologists to statistical analysis. The use of the traditional approach of null‐hypothesis testing has been questioned and an alternative, model selection by information–theoretic methods, has been strongly promoted and is now widely used. For certain types of analysis, information–theoretic approaches offer powerful and compelling advantages over null‐hypothesis testing. The benefits of information–theoretic methods are often framed as criticisms of null‐hypothesis testing. We argue that many of these criticisms are neither irremediable nor always fair. Many are criticisms of the paradigm's application, rather than of its formulation. Information–theoretic methods are equally vulnerable to many such misuses. Care must be taken", "oa": true, "pdf_url": "https://onlinelibrary.wiley.com/doi/pdfdirect/10.1111/j.1365-2664.2005.01002.x", "local_pdf": "", "api": ""}, {"title": "A central limit theorem for quadratic forms in strongly dependent linear variables and its application to asymptotical normality of Whittle's estimate", "doi": "https://doi.org/10.1007/bf01207515", "year": 1990, "authors": ["Liudas Giraitis", "Донатас Сургайлис"], "source": "Probability Theory and Related Fields", "cited": 344, "abstract": "", "oa": true, "pdf_url": "https://link.springer.com/content/pdf/10.1007/BF01207515.pdf", "local_pdf": "", "api": ""}, {"title": "Break Point Estimation and Spurious Rejections With Endogenous Unit Root Tests", "doi": "https://doi.org/10.1111/1468-0084.00234", "year": 2001, "authors": ["Junsoo Lee", "Mark C. Strazicich"], "source": "Oxford Bulletin of Economics and Statistics", "cited": 332, "abstract": "This paper examines the accuracy of break point estimation using the endogenous break unit root tests of Zivot and Andrews (1992) and Perron (1997). We find that these tests tend to identify the break point incorrectly at one‐period behind (TB‐1) the true break point (TB), where bias in estimating the persistence parameter and spurious rejections are the greatest. In addition, this outcome occurs under the null and alternative hypotheses, and more so as the magnitude of the break increases. Consequences of utilizing these endogenous break tests are similar to (incorrectly) omitting the break term Bt in Perron's (1989) exogenous test.", "oa": true, "pdf_url": "https://doi.org/10.1111/1468-0084.00234", "local_pdf": "", "api": ""}, {"title": "Chi-square test and its application in hypothesis testing", "doi": "https://doi.org/10.4103/2395-5414.157577", "year": 2015, "authors": ["Richa Singhal", "Rakesh Rana"], "source": "Journal of the Practice of Cardiovascular Sciences", "cited": 314, "abstract": "In medical research, there are studies which often collect data on categorical variables that can be summarized as a series of counts. These counts are commonly arranged in a tabular format known as a contingency table. The chi-square test statistic can be used to evaluate whether there is an association between the rows and columns in a contingency table. More specifically, this statistic can be used to determine whether there is any difference between the study groups in the proportions of the risk factor of interest. Chi-square test and the logic of hypothesis testing were developed by Karl Pearson. This article describes in detail what is a chi-square test, on which type of data it is used, the assumptions associated with its application, how to manually calculate it and how to make us", "oa": true, "pdf_url": "https://doi.org/10.4103/2395-5414.157577", "local_pdf": "", "api": ""}, {"title": "The Law of Large Numbers and the Central Limit Theorem in Banach Spaces", "doi": "https://doi.org/10.1214/aop/1176996029", "year": 1976, "authors": ["J. Hoffmann-Jørgensen", "Gilles Pisier"], "source": "The Annals of Probability", "cited": 312, "abstract": "Let $X_1, X_2, \\cdots$ be independent random variables with values in a Banach space $E$. It is then shown that Chung's version of the strong law of large numbers holds, if and only if $E$ is of type $p$. If the $X_n$'s are identically distributed, then it is shown that the central limit theorem is valid, if and only if $E$ is of type 2. Similar results are obtained for vectorvalued martingales.", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-probability/volume-4/issue-4/The-Law-of-Large-Numbers-and-the-Central-Limit-Theorem/10.1214/aop/1176996029.pdf", "local_pdf": "", "api": ""}, {"title": "On the Central Limit Theorem for Stationary Mixing Random Fields", "doi": "https://doi.org/10.1214/aop/1176993726", "year": 1982, "authors": ["Erwin Bolthausen"], "source": "The Annals of Probability", "cited": 299, "abstract": "A simple proof of a central limit theorem for stationary random fields under mixing conditions is given, generalizing some results obtained by more complicated methods, e.g. Bernstein's method.", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-probability/volume-10/issue-4/On-the-Central-Limit-Theorem-for-Stationary-Mixing-Random-Fields/10.1214/aop/1176993726.pdf", "local_pdf": "", "api": ""}, {"title": "Objections to Bayesian statistics", "doi": "https://doi.org/10.1214/08-ba318", "year": 2008, "authors": ["Andrew Gelman"], "source": "Bayesian Analysis", "cited": 284, "abstract": "Bayesian inference is one of the more controversial approaches to statistics. The fundamental objections to Bayesian methods are twofold: on one hand, Bayesian methods are presented as an automatic inference engine, and this raises suspicion in anyone with applied experience. The second objection to Bayes comes from the opposite direction and addresses the subjective strand of Bayesian inference. This article presents a series of objections to Bayesian inference, written in the voice of a hypothetical anti-Bayesian statistician. The article is intended to elicit elaborations and extensions of these and other arguments from non-Bayesians and responses from Bayesians who might have different perspectives on these issues.", "oa": true, "pdf_url": "https://projecteuclid.org/journals/bayesian-analysis/volume-3/issue-3/Objections-to-Bayesian-statistics/10.1214/08-BA318.pdf", "local_pdf": "", "api": ""}, {"title": "On the Probability Theory of Linkage in Mendelian Heredity", "doi": "https://doi.org/10.1214/aoms/1177731313", "year": 1944, "authors": ["Hilda Geiringer"], "source": "The Annals of Mathematical Statistics", "cited": 283, "abstract": "", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-mathematical-statistics/volume-15/issue-1/On-the-Probability-Theory-of-Linkage-in-Mendelian-Heredity/10.1214/aoms/1177731313.pdf", "local_pdf": "", "api": ""}, {"title": "Central limit theorem for linear eigenvalue statistics of random matrices with independent entries", "doi": "https://doi.org/10.1214/09-aop452", "year": 2009, "authors": ["Anna Lytova", "L. А. Pastur"], "source": "The Annals of Probability", "cited": 274, "abstract": "We consider n×n real symmetric and Hermitian Wigner random matrices n−1/2W with independent (modulo symmetry condition) entries and the (null) sample covariance matrices n−1X*X with independent entries of m×n matrix X. Assuming first that the 4th cumulant (excess) κ4 of entries of W and X is zero and that their 4th moments satisfy a Lindeberg type condition, we prove that linear statistics of eigenvalues of the above matrices satisfy the central limit theorem (CLT) as n→∞, m→∞, m/n→c∈[0, ∞) with the same variance as for Gaussian matrices if the test functions of statistics are smooth enough (essentially of the class C5). This is done by using a simple “interpolation trick” from the known results for the Gaussian matrices and the integration by parts, presented in the form of certain differ", "oa": true, "pdf_url": "https://projecteuclid.org/journals/annals-of-probability/volume-37/issue-5/Central-limit-theorem-for-linear-eigenvalue-statistics-of-random-matrices/10.1214/09-AOP452.pdf", "local_pdf": "", "api": ""}]}}}